-- Esquema SQLite do Lyra Study (fonte única: o app Flutter e tools/export_mobile.py usam este arquivo)
-- k/v = configurações em JSON. As demais tabelas são relacionais, com chaves estrangeiras e CHECKs.
CREATE TABLE IF NOT EXISTS kv (k TEXT PRIMARY KEY, v TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS subjects (name TEXT PRIMARY KEY, difficulty INTEGER NOT NULL CHECK (difficulty BETWEEN 1 AND 5), position INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS sessions (day TEXT NOT NULL, subject TEXT NOT NULL, minutes INTEGER NOT NULL CHECK (minutes >= 0), simulated INTEGER NOT NULL DEFAULT 0, PRIMARY KEY (day, subject));
CREATE TABLE IF NOT EXISTS custom_tasks (id TEXT PRIMARY KEY, day TEXT NOT NULL, title TEXT NOT NULL, at_time TEXT NOT NULL DEFAULT '');
CREATE INDEX IF NOT EXISTS idx_tasks_day ON custom_tasks(day);
CREATE TABLE IF NOT EXISTS todo_done (k TEXT PRIMARY KEY);
CREATE TABLE IF NOT EXISTS exams (id TEXT PRIMARY KEY, name TEXT NOT NULL, day TEXT NOT NULL, max_q INTEGER NOT NULL DEFAULT 0, hits INTEGER NOT NULL DEFAULT 0, scale INTEGER NOT NULL DEFAULT 0, annulled INTEGER NOT NULL DEFAULT 0, score10 REAL NOT NULL DEFAULT 0, weighted INTEGER NOT NULL DEFAULT 0, city_year INTEGER NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS idx_exams_day ON exams(day);
CREATE TABLE IF NOT EXISTS exam_subjects (exam_id TEXT NOT NULL REFERENCES exams(id) ON DELETE CASCADE, subject TEXT NOT NULL, hits INTEGER NOT NULL, total INTEGER NOT NULL, orig_hits INTEGER NOT NULL, orig_total INTEGER NOT NULL, annulled INTEGER NOT NULL DEFAULT 0, annulled_hit INTEGER NOT NULL DEFAULT 0, score REAL NOT NULL, weight REAL NOT NULL DEFAULT 1, PRIMARY KEY (exam_id, subject));
CREATE TABLE IF NOT EXISTS attachments (id INTEGER PRIMARY KEY AUTOINCREMENT, exam_id TEXT NOT NULL REFERENCES exams(id) ON DELETE CASCADE, name TEXT NOT NULL, file TEXT NOT NULL, size INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS city_tiles (idx INTEGER PRIMARY KEY, building TEXT, level INTEGER NOT NULL DEFAULT 0, xp REAL NOT NULL DEFAULT 0, day TEXT NOT NULL DEFAULT '', minutes INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS city_history (year INTEGER PRIMARY KEY, completed_on TEXT NOT NULL, data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS layout_perm (k TEXT PRIMARY KEY, perm TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS cards (id TEXT PRIMARY KEY, subject TEXT NOT NULL, category TEXT NOT NULL DEFAULT '', sub TEXT NOT NULL DEFAULT '', q TEXT NOT NULL DEFAULT '', a TEXT NOT NULL DEFAULT '', q_img TEXT, a_img TEXT, due TEXT NOT NULL, interval_days INTEGER NOT NULL DEFAULT 0, ease REAL NOT NULL DEFAULT 2.5, reps INTEGER NOT NULL DEFAULT 0, extra TEXT NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS pdf_done (path TEXT PRIMARY KEY);
